import java.util.*;

class Solution {
  public int secondMinimum(int n, int[][] edges, int time, int change) {
    List<Integer>[] g = new List[n + 1];
    for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    int[][] dist = new int[n + 1][2];
    for (int[] a : dist) Arrays.fill(a, Integer.MAX_VALUE);
    ArrayDeque<int[]> q = new ArrayDeque<>();
    dist[1][0] = 0;
    q.add(new int[] {1, 0});
    while (!q.isEmpty()) {
      int[] cur = q.poll();
      int u = cur[0], rank = cur[1];
      for (int v : g[u]) {
        int nd = dist[u][rank] + 1;
        if (nd < dist[v][0]) {
          dist[v][1] = dist[v][0];
          dist[v][0] = nd;
          q.add(new int[] {v, 0});
        } else if (nd > dist[v][0] && nd < dist[v][1]) {
          dist[v][1] = nd;
          q.add(new int[] {v, 1});
        }
      }
    }
    int t = 0;
    for (int i = 0; i < dist[n][1]; i++) {
      if ((t / change) % 2 == 1) t += change - t % change;
      t += time;
    }
    return t;
  }
}
